SELECT *
FROM gl_member_profile
WHERE tenant_id = #{tenantId}
  AND username = #{username}
  AND del_flag = '0'
LIMIT 1

SELECT *
FROM gl_member_profile
WHERE tenant_id = #{tenantId}
  AND id = #{memberId}
  AND del_flag = '0'
LIMIT 1

SELECT *
FROM gl_member_profile
WHERE tenant_id = #{tenantId}
  AND member_no = #{memberNo}
  AND del_flag = '0'
LIMIT 1
